#!/usr/bin/env python3

import csv
import json
from difflib import get_close_matches

def parse_int(v):
    """Parse integer values, handling commas and string formatting"""
    if isinstance(v, (int, float)):
        return int(v)
    return int(str(v).strip().replace(",", ""))

def fuzzy_match_precinct(target, candidates, cutoff=0.6):
    """Fuzzy match precinct name with typo tolerance"""
    matches = get_close_matches(target, candidates, n=1, cutoff=cutoff)
    return matches[0] if matches else None

def classify_severity(d_type, diff=None):
    """Classify discrepancy severity"""
    if d_type in ("impossible_value", "precinct_missing", "candidate_missing"):
        return "high"
    # vote_count_mismatch: grade by difference
    if diff <= 10:
        return "low"
    if diff <= 100:
        return "medium"
    return "high"

def load_official_results(filepath):
    """Load official results CSV into structured format"""
    precincts = {}
    registered_voters = {}

    with open(filepath, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            precinct = row['precinct_name']
            candidate = row['candidate']
            votes = int(row['votes'])
            registered = int(row['registered_voters'])

            if precinct not in precincts:
                precincts[precinct] = {}
                registered_voters[precinct] = registered

            precincts[precinct][candidate] = votes

    return precincts, registered_voters

def load_tally_sheets(filepath):
    """Load tally sheets JSON into structured format"""
    with open(filepath, 'r') as f:
        data = json.load(f)

    precincts = {}
    for sheet in data['sheets']:
        precinct = sheet['precinct']
        precincts[precinct] = {}

        for result in sheet['results']:
            candidate = result['candidate']
            votes = parse_int(result['votes'])
            precincts[precinct][candidate] = votes

    return precincts

def audit_election_data():
    """Perform comprehensive election audit"""
    # Load data
    official_precincts, registered_voters = load_official_results('/root/official_results.csv')
    tally_precincts = load_tally_sheets('/root/tally_sheets.json')

    discrepancies = []
    tally_precinct_names = list(tally_precincts.keys())

    # Track for summary statistics
    precincts_matched = 0

    # Compare each official precinct
    for official_precinct in official_precincts.keys():
        # Fuzzy match precinct name
        matched_precinct = fuzzy_match_precinct(official_precinct, tally_precinct_names)

        if matched_precinct is None:
            # Entire precinct missing from tally sheets
            discrepancies.append({
                "precinct": official_precinct,
                "candidate": None,
                "discrepancy_type": "precinct_missing",
                "official_votes": None,
                "tally_votes": None,
                "difference": None,
                "severity": "high"
            })
            continue

        precincts_matched += 1

        # Check each candidate in this precinct
        official_candidates = official_precincts[official_precinct]
        tally_candidates = tally_precincts[matched_precinct]

        for candidate, official_votes in official_candidates.items():
            if candidate not in tally_candidates:
                # Candidate missing from tally sheet
                discrepancies.append({
                    "precinct": official_precinct,
                    "candidate": candidate,
                    "discrepancy_type": "candidate_missing",
                    "official_votes": None,
                    "tally_votes": None,
                    "difference": None,
                    "severity": "high"
                })
            else:
                tally_votes = tally_candidates[candidate]
                registered = registered_voters[official_precinct]

                if tally_votes > registered:
                    # Impossible value - more votes than registered voters
                    diff = abs(tally_votes - official_votes)
                    discrepancies.append({
                        "precinct": official_precinct,
                        "candidate": candidate,
                        "discrepancy_type": "impossible_value",
                        "official_votes": official_votes,
                        "tally_votes": tally_votes,
                        "difference": diff,
                        "severity": "high"
                    })
                elif tally_votes != official_votes:
                    # Vote count mismatch
                    diff = abs(tally_votes - official_votes)
                    discrepancies.append({
                        "precinct": official_precinct,
                        "candidate": candidate,
                        "discrepancy_type": "vote_count_mismatch",
                        "official_votes": official_votes,
                        "tally_votes": tally_votes,
                        "difference": diff,
                        "severity": classify_severity("vote_count_mismatch", diff)
                    })

    # Sort discrepancies: high severity first, then alphabetical by precinct
    sev_order = {"high": 0, "medium": 1, "low": 2}
    discrepancies.sort(key=lambda d: (sev_order[d["severity"]], d["precinct"] or ""))

    # Calculate summary statistics
    precincts_with_issues = {d["precinct"] for d in discrepancies if d["precinct"]}

    severity_counts = {"low": 0, "medium": 0, "high": 0}
    type_counts = {
        "vote_count_mismatch": 0,
        "impossible_value": 0,
        "candidate_missing": 0,
        "precinct_missing": 0
    }

    for d in discrepancies:
        severity_counts[d["severity"]] += 1
        type_counts[d["discrepancy_type"]] += 1

    # Generate audit report
    audit_report = {
        "summary": {
            "total_precincts_official": len(official_precincts),
            "total_precincts_tally": len(tally_precincts),
            "precincts_matched": precincts_matched,
            "precincts_with_discrepancies": len(precincts_with_issues),
            "total_discrepancies": len(discrepancies),
            "discrepancies_by_severity": severity_counts,
            "discrepancies_by_type": type_counts
        },
        "discrepancies": discrepancies
    }

    # Write audit report
    with open('/root/audit_report.json', 'w') as f:
        json.dump(audit_report, f, indent=2)

    print(f"Audit complete. Found {len(discrepancies)} discrepancies.")
    print(f"Report written to /root/audit_report.json")

    return audit_report

if __name__ == "__main__":
    audit_election_data()

